fn hermemulx(c: Vec<f64>) -> Vec<f64> {
    let n = c.len();
    let mut result = Vec::with_capacity(n + 1);
    result.push(0.0);

    // For 1 <= i < n, set result[i + 1] = c[i]
    // (Indices are valid because i starts at 1 and ends at n-1.)
    for i in 1..n {
        result.push(c[i]);
    }

    // Ensure length is exactly n + 1 (pad with 0.0 if n <= 1).
    while result.len() < n + 1 {
        result.push(0.0);
    }

    result
}